import gzip, hashlib
from pathlib import Path

paths = {
    \"original_forward\": Path(\"data/inputs/short_reads/pair/forward/forward.fastqsanger.gz\"),
    \"original_reverse\": Path(\"data/inputs/short_reads/pair/reverse/reverse.fastqsanger.gz\"),
    \"filtered_forward\": Path(\"final_answer/filtered_forward.fastqsanger.gz\"),
    \"filtered_reverse\": Path(\"final_answer/filtered_reverse.fastqsanger.gz\"),
}

def records(path):
    with gzip.open(path, \"rb\") as handle:
        while True:
            rec = tuple(handle.readline() for _ in range(4))
            if not rec[0]:
                if any(rec[1:]):
                    raise SystemExit(f\"partial FASTQ record in {path}\")
                return
            if any(not x for x in rec[1:]):
                raise SystemExit(f\"partial FASTQ record in {path}\")
            if not rec[0].startswith(b\"@\") or not rec[2].startswith(b\"+\"):
                raise SystemExit(f\"invalid FASTQ structure in {path}\")
            if len(rec[1].rstrip(b\"\\r\\n\")) "'!= len(rec[3].rstrip(b"'"\\r\\n\")):
                raise SystemExit(f\"sequence/quality length mismatch in {path}\")
            yield rec

def rid(rec):
    token = rec[0].split(None, 1)[0]
    if token.endswith((b\"/1\", b\"/2\")):
        token = token[:-2]
    return token

def verify_unchanged_subset(original, filtered):
    source = iter(records(original))
    source_rec = next(source, None)
    count = 0
    for out_rec in records(filtered):
        out_id = rid(out_rec)
        while source_rec is not None and rid(source_rec) "'!= out_id:
            source_rec = next(source, None)
        if source_rec is None:
            raise SystemExit(f"filtered ID absent or out of order: {out_id!r}")
        if source_rec != out_rec:
            raise SystemExit(f"retained record modified: {out_id!r}")
        count += 1
        source_rec = next(source, None)
    return count

f_iter = records(paths["filtered_forward"])
r_iter = records(paths["filtered_reverse"])
pair_count = 0
while True:
    f = next(f_iter, None)
    r = next(r_iter, None)
    if f is None or r is None:
        if f is not None or r is not None:
            raise SystemExit("mate files have different record counts")
        break
    if rid(f) != rid(r):
        raise SystemExit(f"mate desynchronization at pair {pair_count + 1}: {rid(f)!r} != {rid(r)!r}")
    pair_count += 1

forward_subset = verify_unchanged_subset(paths["original_forward"], paths["filtered_forward"])
reverse_subset = verify_unchanged_subset(paths["original_reverse"], paths["filtered_reverse"])
if (pair_count, forward_subset, reverse_subset) != (72867, 72867, 72867):
    raise SystemExit(f"unexpected retained counts: {pair_count}, {forward_subset}, {reverse_subset}")

for label, path in paths.items():
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    count = sum(1 for _ in records(path))
    print(f"{label}'"\\trecords={count}\\tsha256={digest}\")
print(\"synchronization=ok\")
print(\"retained_records_unchanged=ok\")
